const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [n, m] = input;
const a = input.slice(2, 2 + n);
const b = input.slice(2 + n, 2 + n + m);

const common = a.filter(digit => b.includes(digit));

if (common.length > 0) {
    console.log(Math.min(...common));
} else {
    const x = Math.min(...a);
    const y = Math.min(...b);
    console.log(Math.min(x, y) * 10 + Math.max(x, y));
}

